{
  "ruleset_id": "kulturnyiy_grant_gorodskaya_scena",
  "rules": [
    {
      "description": "Project leader must be of legal adult age (at least 18 years old).",
      "severity": "critical",
      "category": "age",
      "condition": {
        "field": "team.project_lead_age",
        "op": "ge",
        "value": 18
      }
    },
    {
      "description": "Applicant must provide co-financing of at least 20% of the budget.",
      "severity": "critical",
      "category": "co_financing",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "For in-person events, venue consent must be provided.",
      "severity": "critical",
      "category": "venue_consent",
      "condition": {
        "field": "documents.venue_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Requested grant amount must not exceed 1,500,000 rubles.",
      "severity": "critical",
      "category": "requested_amount",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 1500000
      }
    }
  ]
}

{
  "ruleset_id": "programma_dopolnitelnogo_obrazovaniya",
  "rules": [
    {
      "description": "Лицензия на образовательную деятельность должна быть действующей и предоставленной.",
      "severity": "critical",
      "category": "license",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Общий объём программы должен быть не менее 72 часов.",
      "severity": "critical",
      "category": "program_hours",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "Доля преподавателей с профильной квалификацией должна быть не менее 80%.",
      "severity": "critical",
      "category": "teacher_qualification",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Формат реализации программы должен быть только очным или смешанным.",
      "severity": "critical",
      "category": "delivery_format",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "energy_efficiency_subsidy",
  "rules": [
    {
      "description": "Проект должен снижать потребление энергии как минимум на 20 процентов.",
      "severity": "critical",
      "category": "energy_reduction_min",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Доля софинансирования заявителя должна быть не менее 30 процентов.",
      "severity": "critical",
      "category": "cofinancing_min",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "К заявке должен быть приложен технический паспорт объекта.",
      "severity": "critical",
      "category": "technical_passport_required",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Работы должны быть завершены не позднее 31 декабря 2027 года.",
      "severity": "critical",
      "category": "completion_deadline",
      "condition": {
        "field": "project.completion_date",
        "op": "le",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "nordstar_main_track_2-4",
  "rules": [
    {
      "description": "Applicant must have been registered for at least 24 months for the main grant track.",
      "severity": "critical",
      "category": "registration_duration",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "ge",
        "value": 24
      }
    },
    {
      "description": "Requested grant amount must not exceed 250000 euros.",
      "severity": "critical",
      "category": "requested_amount_limit",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "le",
        "value": 250000
      }
    },
    {
      "description": "An independent audit report for the last completed fiscal year must be attached.",
      "severity": "critical",
      "category": "audit_report_required",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Submission date for the 2027 cycle must be on or before 31 March 2027.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "le",
        "value": "2027-03-31"
      }
    },
    {
      "description": "Declared headcount must match the headcount stated in the annual report.",
      "severity": "critical",
      "category": "headcount_consistency",
      "condition": {
        "field": "org_v2.declared_headcount",
        "op": "consistent",
        "value": [
          "org_v2.declared_headcount",
          "annual_report.headcount"
        ]
      }
    },
    {
      "description": "Annual report must be prepared in IFRS.",
      "severity": "minor",
      "category": "reporting_standard_ifrs",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": true
      }
    }
  ]
}

{
  "ruleset_id": "fond_primer_2026_1",
  "rules": [
    {
      "description": "The applicant organization must have been registered for at least 12 months by submission date.",
      "severity": "critical",
      "category": "eligibility",
      "condition": {
        "field": "application_form.months_registered",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "The requested total amount must not exceed 100000 EUR.",
      "severity": "major",
      "category": "budget_limit",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "le",
        "value": 100000
      }
    },
    {
      "description": "Equipment costs may not exceed 40 percent of the total budget.",
      "severity": "major",
      "category": "budget_share",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "le",
        "value": 40
      }
    },
    {
      "description": "The full application package must include the application form.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The full application package must include the detailed budget.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The full application package must include the registration certificate.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The full application package must include the latest financial statement.",
      "severity": "critical",
      "category": "documents",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Applications must be submitted no later than 2026-10-01 (inclusive).",
      "severity": "major",
      "category": "submission",
      "condition": {
        "field": "application_form.submission_date",
        "op": "le",
        "value": "2026-10-01"
      }
    },
    {
      "description": "The application form must be signed by the legal representative.",
      "severity": "critical",
      "category": "signature",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The requested amount in the application form must exactly match the detailed budget total.",
      "severity": "major",
      "category": "consistency",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "consistent",
        "value": [
          "budget.totals.total"
        ]
      }
    },
    {
      "description": "Financial statements must cover FY2025.",
      "severity": "minor",
      "category": "finance_period",
      "condition": {
        "field": "finance_statement.period",
        "op": "eq",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "capital_repair_program",
  "rules": [
    {
      "description": "The building construction year must be 2005 or earlier.",
      "severity": "critical",
      "category": "construction_year",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Owner approval percentage must be at least 66%.",
      "severity": "critical",
      "category": "owner_approval",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "A defect inspection report must be attached to the application.",
      "severity": "critical",
      "category": "defect_report",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The application submission date must be on or before 2027-04-01.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "zakupka_medicinskih_izdelij",
  "rules": [
    {
      "description": "Документ о регистрации товара должен быть представлен.",
      "severity": "critical",
      "category": "registration",
      "condition": {
        "field": "documents.medical_registration.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "На дату поставки остаточный срок годности товара должен быть не менее 12 месяцев.",
      "severity": "critical",
      "category": "shelf_life",
      "condition": {
        "field": "product.expiry_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Для изделий, требующих холодовой цепи, обязан быть представлен протокол соблюдения холодовой цепи.",
      "severity": "critical",
      "category": "cold_chain",
      "condition": {
        "field": "documents.cold_chain_protocol.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Страна происхождения должна быть Россией или государством ЕАЭС.",
      "severity": "critical",
      "category": "origin",
      "condition": {
        "field": "product.origin_country",
        "op": "in",
        "value": ["Россия", "ЕАЭС"]
      }
    }
  ]
}

{
  "ruleset_id": "lgotnyy_mikrozaem_dlya_msp",
  "rules": [
    {
      "description": "Annual company revenue must not exceed 120,000,000 RUB",
      "severity": "critical",
      "category": "annual_revenue_limit",
      "condition": {
        "field": "company.annual_revenue_rub",
        "op": "le",
        "value": 120000000
      }
    },
    {
      "description": "Company must have no overdue debt",
      "severity": "critical",
      "category": "overdue_debt_absence",
      "condition": {
        "field": "company.overdue_debt",
        "op": "eq",
        "value": 0
      }
    },
    {
      "description": "At least 51% of ownership must belong to Russian owners",
      "severity": "critical",
      "category": "russian_ownership_min",
      "condition": {
        "field": "company.russian_ownership_pct",
        "op": "ge",
        "value": 51
      }
    },
    {
      "description": "Requested loan amount must not exceed 10,000,000 RUB",
      "severity": "critical",
      "category": "loan_amount_limit",
      "condition": {
        "field": "loan.requested_rub",
        "op": "le",
        "value": 10000000
      }
    }
  ]
}

{
  "ruleset_id": "municipal-subsidy-2026",
  "rules": [
    {
      "description": "Applicant must be registered for at least 12 months.",
      "severity": "critical",
      "category": "registration_duration",
      "condition": {
        "field": "applicant.registration_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Requested subsidy amount must not exceed 5,000,000 RUB.",
      "severity": "critical",
      "category": "requested_amount_limit",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 5000000
      }
    },
    {
      "description": "Financial statement for the last year must be attached to the application.",
      "severity": "critical",
      "category": "financial_statement_required",
      "condition": {
        "field": "documents.financial_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Application submission date must be on or before 2026-09-15.",
      "severity": "critical",
      "category": "submission_deadline",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2026-09-15"
      }
    },
    {
      "description": "Applicants with tax arrears are not allowed.",
      "severity": "critical",
      "category": "no_tax_arrears",
      "condition": {
        "field": "applicant.tax_arrears",
        "op": "eq",
        "value": false
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-remontnyh-rabot-eligibility",
  "rules": [
    {
      "description": "The supplier must have annual turnover of at least 10,000,000 rubles.",
      "severity": "critical",
      "category": "financial",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "A valid (active) SRO certificate is required.",
      "severity": "critical",
      "category": "documentation",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The supplier's sanctions check status must be \"clear\".",
      "severity": "critical",
      "category": "sanctions",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Bid submissions are accepted no later than 20 November 2026.",
      "severity": "critical",
      "category": "deadline",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "applied_research_competition",
  "rules": [
    {
      "description": "The project leader must have a degree of either \"кандидат наук\" or \"доктор наук\".",
      "severity": "critical",
      "category": "lead_researcher_degree",
      "condition": {
        "field": "researcher.degree",
        "op": "in",
        "value": ["кандидат наук", "доктор наук"]
      }
    },
    {
      "description": "The project leader must have at least 3 peer-reviewed journal publications.",
      "severity": "critical",
      "category": "publications_count",
      "condition": {
        "field": "researcher.peer_reviewed_publications",
        "op": "ge",
        "value": 3
      }
    },
    {
      "description": "Consent for publishing anonymized research data must be provided.",
      "severity": "critical",
      "category": "open_data_consent",
      "condition": {
        "field": "documents.open_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "The budget declared in the application must match the total budget amount in the estimate.",
      "severity": "critical",
      "category": "budget_consistency",
      "condition": {
        "field": "application.declared_budget_rub",
        "op": "consistent",
        "value": ["application.declared_budget_rub", "budget.total_rub"]
      }
    }
  ]
}

{
  "ruleset_id": "social_contract_moscow_region_income_25k",
  "rules": [
    {
      "description": "Household must be located in Moscow or Moscow Oblast.",
      "severity": "critical",
      "category": "region",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": ["Москва", "Московская область"]
      }
    },
    {
      "description": "Monthly income per person must not exceed 25,000 rubles.",
      "severity": "critical",
      "category": "income",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Personal data processing consent must be provided.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Applicant must have employment status 'unemployed' or 'job_seeker'.",
      "severity": "critical",
      "category": "employment_status",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": ["unemployed", "job_seeker"]
      }
    }
  ]
}
